@import "tailwindcss";

:root {
  --surface: #f9f9f7;
  --surface-dim: #dadad8;
  --surface-bright: #f9f9f7;
  --surface-container-lowest: #ffffff;
  --surface-container-low: #f4f4f2;
  --surface-container: #eeeeec;
  --surface-container-high: #e8e8e6;
  --surface-container-highest: #e2e3e1;
  --on-surface: #1a1c1b;
  --on-surface-variant: #424656;
  --inverse-surface: #2f3130;
  --inverse-on-surface: #f1f1ef;
  --outline: #737687;
  --outline-variant: #c3c5d9;
  --surface-tint: #0051e0;
  --primary: #0049cc;
  --on-primary: #ffffff;
  --primary-container: #0b5fff;
  --on-primary-container: #eff0ff;
  --inverse-primary: #b5c4ff;
  --secondary: #565f70;
  --on-secondary: #ffffff;
  --secondary-container: #dae2f8;
  --on-secondary-container: #5c6577;
  --tertiary: #006245;
  --on-tertiary: #ffffff;
  --tertiary-container: #007d5a;
  --on-tertiary-container: #beffdf;
  --emerald-accent: #1FA67A;
  --background: #f9f9f7;
  --on-background: #1a1c1b;
}

@theme {
  --font-display: var(--font-space-grotesk), sans-serif;
  --font-sans: var(--font-inter), sans-serif;
  --font-mono: var(--font-inter), monospace;

  --color-surface-container: var(--surface-container);
  --color-surface-bright: var(--surface-bright);
  --color-surface-container-highest: var(--surface-container-highest);
  --color-on-surface-variant: var(--on-surface-variant);
  --color-surface-dim: var(--surface-dim);
  --color-primary-container: var(--primary-container);
  --color-on-primary-fixed-variant: #003cac;
  --color-on-tertiary: var(--on-tertiary);
  --color-background: var(--background);
  --color-on-error-container: #93000a;
  --color-error: #ba1a1a;
  --color-tertiary-fixed-dim: #63dcac;
  --color-surface-container-lowest: var(--surface-container-lowest);
  --color-secondary-fixed-dim: #bec7db;
  --color-on-secondary-fixed: #131c2b;
  --color-secondary-container: var(--secondary-container);
  --color-on-tertiary-fixed: #002115;
  --color-primary: var(--primary);
  --color-secondary: var(--secondary);
  --color-on-error: #ffffff;
  --color-primary-fixed-dim: #b5c4ff;
  --color-inverse-surface: var(--inverse-surface);
  --color-surface-container-low: var(--surface-container-low);
  --color-on-secondary: #ffffff;
  --color-on-secondary-container: var(--on-secondary-container);
  --color-on-background: var(--on-background);
  --color-surface: var(--surface);
  --color-on-primary: #ffffff;
  --color-surface-variant: #e2e3e1;
  --color-on-surface: var(--on-surface);
  --color-inverse-on-surface: #f1f1ef;
  --color-tertiary: var(--tertiary);
  --color-tertiary-container: var(--tertiary-container);
  --color-outline: var(--outline);
  --color-tertiary-fixed: #81f9c7;
  --color-on-primary-container: var(--on-primary-container);
  --color-on-tertiary-container: var(--on-tertiary-container);
  --color-primary-fixed: #dbe1ff;
  --color-inverse-primary: #b5c4ff;
  --color-error-container: #ffdad6;
  --color-on-secondary-fixed-variant: #3e4758;
  --color-on-primary-fixed: #00164d;
  --color-surface-tint: var(--surface-tint);
  --color-on-tertiary-fixed-variant: #005139;
  --color-surface-container-high: #e8e8e6;
  --color-secondary-fixed: #dae2f8;
  --color-outline-variant: var(--outline-variant);
  --color-emerald-accent: var(--emerald-accent);

  --spacing-margin-desktop: 64px;
  --spacing-unit: 8px;
  --spacing-gutter: 32px;
  --spacing-margin-mobile: 24px;
  --spacing-section-gap-lg: 128px;
  --spacing-container-max: 1440px;
}

body {
  background-color: var(--background);
  color: var(--on-background);
  font-family: var(--font-sans);
}

h1, h2, h3, .font-display {
  font-family: var(--font-display);
}

.blueprint-grid {
  background-image: linear-gradient(rgba(255, 255, 255, 0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.05) 1px, transparent 1px);
  background-size: 40px 40px;
}

.blueprint-grid-dark {
  background-image: linear-gradient(rgba(255, 255, 255, 0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.03) 1px, transparent 1px);
  background-size: 20px 20px;
}

.micro-grid {
  background-image: linear-gradient(rgba(0, 0, 0, 0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0, 0, 0, 0.05) 1px, transparent 1px);
  background-size: 8px 8px;
}

.glass-panel {
  background: rgba(255, 255, 255, 0.03);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.glass-panel-light {
  background: rgba(255, 255, 255, 0.8);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 1);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.05);
}

.scanlines {
  background: linear-gradient(to bottom, rgba(255,255,255,0), rgba(255,255,255,0) 50%, rgba(0,0,0,0.1) 50%, rgba(0,0,0,0.1));
  background-size: 100% 4px;
  pointer-events: none;
}

@keyframes marquee {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

.animate-marquee {
  animation: marquee 30s linear infinite;
}

.animate-marquee:hover {
  animation-play-state: paused;
}

import type { Metadata } from "next";
import { Space_Grotesk, Inter } from "next/font/google";
import "./globals.css";

const spaceGrotesk = Space_Grotesk({
  variable: "--font-space-grotesk",
  subsets: ["latin"],
  weight: ["400", "500", "600", "700"],
});

const inter = Inter({
  variable: "--font-inter",
  subsets: ["latin"],
  weight: ["400", "500", "600", "700"],
});

export const metadata: Metadata = {
  title: "Axon Engineering | Global Infrastructure & Precision Platform",
  description: "Architecting and executing hyper-scale global infrastructure with technical mastery, precision engineering, and unwavering reliability.",
  keywords: ["Engineering", "Global Infrastructure", "Mechanical Systems", "Subsea Engineering", "Process Engineering", "Axon Engineering"],
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html
      lang="en"
      className={`${spaceGrotesk.variable} ${inter.variable} scroll-smooth h-full antialiased`}
    >
      <head>
        <link
          rel="stylesheet"
          href="https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:wght,FILL@100..700,0..1&display=swap"
        />
      </head>
      <body className="min-h-full flex flex-col bg-background text-on-background selection:bg-[#1FA67A] selection:text-white">
        {children}
      </body>
    </html>
  );
}

"use me";
"use client";

import { useState } from "react";
import Navbar from "@/components/Navbar";
import HeroSection from "@/components/HeroSection";
import PrecisionDisciplines, { Discipline } from "@/components/PrecisionDisciplines";
import StrategicPartnerships from "@/components/StrategicPartnerships";
import SectorInsights from "@/components/SectorInsights";
import LifecycleTimeline from "@/components/LifecycleTimeline";
import TechnicalWhitepapers, { Whitepaper } from "@/components/TechnicalWhitepapers";
import HumanCapital from "@/components/HumanCapital";
import GlobalFootprintMap from "@/components/GlobalFootprintMap";
import ConsultationCTA from "@/components/ConsultationCTA";
import Footer from "@/components/Footer";

// Modals
import SearchModal from "@/components/SearchModal";
import ConsultationModal from "@/components/ConsultationModal";
import DisciplineModal from "@/components/DisciplineModal";
import WhitepaperModal from "@/components/WhitepaperModal";
import LeadershipModal from "@/components/LeadershipModal";

export default function Home() {
  const [searchOpen, setSearchOpen] = useState(false);
  const [consultationOpen, setConsultationOpen] = useState(false);
  const [selectedDiscipline, setSelectedDiscipline] = useState<Discipline | null>(null);
  const [selectedWhitepaper, setSelectedWhitepaper] = useState<Whitepaper | null>(null);
  const [leadershipOpen, setLeadershipOpen] = useState(false);

  const scrollToDisciplines = () => {
    const el = document.getElementById("disciplines");
    if (el) el.scrollIntoView({ behavior: "smooth" });
  };

  return (
    <div className="relative min-h-screen bg-background text-on-background">
      {/* Background Grids & Scans */}
      <div className="fixed inset-0 micro-grid pointer-events-none z-[-1] opacity-50" />
      <div className="fixed inset-0 scanlines pointer-events-none z-50 mix-blend-overlay opacity-20" />

      {/* Top Navbar */}
      <Navbar
        onOpenSearch={() => setSearchOpen(true)}
        onOpenConsultation={() => setConsultationOpen(true)}
      />

      {/* Main Content Area */}
      <main className="w-full">
        {/* 1. Hero Section */}
        <HeroSection
          onExplore={scrollToDisciplines}
          onOpenConsultation={() => setConsultationOpen(true)}
        />

        {/* 2. Precision Disciplines Bento Grid */}
        <PrecisionDisciplines
          onSelectDiscipline={(discipline) => setSelectedDiscipline(discipline)}
        />

        {/* 3. Strategic Partnerships Infinite Ticker */}
        <StrategicPartnerships />

        {/* 4. Human Element Sector Insights */}
        <SectorInsights
          onOpenCaseStudy={() =>
            setSelectedWhitepaper({
              id: "cs-human-scale",
              category: "HYPER-SCALE INFRASTRUCTURE",
              date: "AUG 2026",
              tag: "CASE STUDY",
              title: "The Human Element of Hyper-Scale Infrastructure",
              summary:
                "Behind every holographic projection and smart city blueprint is a team of visionary engineers. We blend Fortune 500 sophistication with rigorous technical execution.",
              image:
                "https://lh3.googleusercontent.com/aida-public/AB6AXuAGilywHHJWKX8_xH8PH0-KU7bj4qbyZppnHnxDo0U23bbFMfCUR41S16mbhdI136MrakXpNGOdKx8kiruKm2e25PfVCKDyWW6FgGXwy2hM_Qk9i9gJtnF2xfQCDonydx-2yaEmo0CuhkhRIkwg_KMuHKzzNKe9DwJNcJDrOnKMXJKgqFzUv1g1Airpk9l1_Dcyh_Qy6qhSHBtsDtzjAu322hTarK3MSeUJVJquxBk4idUo0YjY9_c",
              readTime: "10 min read",
              author: "Axon Senior Leadership Council",
              takeaways: [
                "100% digital twin pre-validation before on-site ground break.",
                "Cross-disciplinary integration between material scientists and SCADA architects.",
                "Zero safety incidents across 3.4M operational hours.",
              ],
            })
          }
        />

        {/* 5. Axon Engineering Lifecycle */}
        <LifecycleTimeline />

        {/* 6. Technical Whitepapers Grid */}
        <TechnicalWhitepapers
          onSelectWhitepaper={(whitepaper) => setSelectedWhitepaper(whitepaper)}
        />

        {/* 7. Leadership & Human Capital */}
        <HumanCapital onOpenLeadership={() => setLeadershipOpen(true)} />

        {/* 8. Global Footprint Map */}
        <GlobalFootprintMap />

        {/* 9. Initiate Consultation CTA */}
        <ConsultationCTA onOpenConsultation={() => setConsultationOpen(true)} />
      </main>

      {/* Footer */}
      <Footer />

      {/* Interactive Modals */}
      <SearchModal
        isOpen={searchOpen}
        onClose={() => setSearchOpen(false)}
        onSelectDiscipline={(d) => setSelectedDiscipline(d)}
        onSelectWhitepaper={(w) => setSelectedWhitepaper(w)}
      />

      <ConsultationModal
        isOpen={consultationOpen}
        onClose={() => setConsultationOpen(false)}
      />

      <DisciplineModal
        discipline={selectedDiscipline}
        onClose={() => setSelectedDiscipline(null)}
        onOpenConsultation={() => setConsultationOpen(true)}
      />

      <WhitepaperModal
        whitepaper={selectedWhitepaper}
        onClose={() => setSelectedWhitepaper(null)}
      />

      <LeadershipModal
        isOpen={leadershipOpen}
        onClose={() => setLeadershipOpen(false)}
      />
    </div>
  );
}

