                >
                  {link.name}
                </a>
              ))}
            </nav>
            <button
              onClick={() => {
                setMobileMenuOpen(false);
                onOpenConsultation();
              }}
              className="w-full bg-[#0049cc] text-white px-6 py-4 rounded-xl font-sans text-xs font-bold uppercase tracking-widest transition-colors mt-4"
            >
              Consultation
            </button>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.header>
  );
}

