}
::-webkit-scrollbar-thumb:hover {
  background: var(--primary);
}
html {
  scrollbar-width: thin;
  scrollbar-color: #c3c5d9 var(--surface-container-low);
}

/* Text selection */
::selection {
  background: rgba(31, 166, 122, 0.85);
  color: #ffffff;
}

/* Accessible focus ring */
a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: 2px solid var(--primary-container);
  outline-offset: 2px;
  border-radius: 4px;
}

/* Balanced headings for premium editorial wrapping */
h1, h2, h3 {
  text-wrap: balance;
}
p {
  text-wrap: pretty;
}

/* Keyframes */
@keyframes fade-up {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes float-soft {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-8px); }
}
@keyframes shimmer {
  100% { transform: translateX(100%); }
}
@keyframes modal-in {
  from { opacity: 0; transform: translateY(8px) scale(0.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes ping-ring {
  0% { transform: scale(0.9); opacity: 0.6; }
  70%, 100% { transform: scale(2.2); opacity: 0; }
}

/* Utility classes */
.animate-float-soft {
  animation: float-soft 6s ease-in-out infinite;
}

.reveal {
  opacity: 0;
}
.reveal.is-visible {
  animation: fade-up 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

/* Modal entrance (used by *Modal components with .animate-in) */
.animate-in {
  animation: fade-in 0.2s ease-out both;
}
.modal-surface {
  animation: modal-in 0.32s cubic-bezier(0.16, 1, 0.3, 1) both;
}

/* Shimmer sweep for premium buttons / cards */
.shimmer-sweep {
  position: relative;
  overflow: hidden;
}
.shimmer-sweep::after {
  content: "";
  position: absolute;
  inset: 0;
  transform: translateX(-100%);
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 255, 255, 0.18),
    transparent
  );
}
.shimmer-sweep:hover::after {
  animation: shimmer 0.9s ease;
}

/* Pulsing location ring */
.node-ring::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 9999px;
  border: 1px solid currentColor;
  animation: ping-ring 2.4s cubic-bezier(0, 0, 0.2, 1) infinite;
}

/* Respect reduced motion preferences */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}

