"use client";

import { useState } from "react";
import { motion } from "framer-motion";
import { cn } from "@/lib/utils";

interface HubLocation {
  id: string;
  name: string;
  type: "HQ" | "Active Operation";
  coords: { x: number; y: number }; // Percentage relative position
  city: string;
  engineers: number;
  activeProjects: number;
  specialization: string;
}

const hubs: HubLocation[] = [
  {
    id: "na-hub",
    name: "North America Innovation Hub",
    type: "Active Operation",
    coords: { x: 22, y: 38 },
    city: "Houston, TX",
    engineers: 320,
    activeProjects: 142,
    specialization: "Subsea & Heavy Structural Systems",
  },
  {
    id: "eu-hq",
    name: "European Executive HQ",
    type: "HQ",
    coords: { x: 49, y: 30 },
    city: "Zurich, Switzerland",
    engineers: 450,
    activeProjects: 210,
    specialization: "Precision Turbines & Process Control",
  },
  {
    id: "me-hub",
    name: "Middle East Energy Hub",
    type: "Active Operation",
    coords: { x: 60, y: 46 },
    city: "Dubai, UAE",
    engineers: 280,
    activeProjects: 95,
    specialization: "Desalination & Solar Hydro-Infra",
  },
  {
    id: "apac-hub",
    name: "APAC Robotics & Subsea Center",
    type: "Active Operation",
    coords: { x: 79, y: 56 },
    city: "Singapore",
    engineers: 390,
    activeProjects: 168,
    specialization: "Autonomous Subsea Robotics & AI",
  },
];

// Ordered connection routes between hubs (great-circle style arcs)
const routes = [
  ["na-hub", "eu-hq"],
  ["eu-hq", "me-hub"],
  ["me-hub", "apac-hub"],
  ["eu-hq", "apac-hub"],
];

function hubById(id: string) {
  return hubs.find((h) => h.id === id)!;
}

function arcPath(a: HubLocation, b: HubLocation) {
  const mx = (a.coords.x + b.coords.x) / 2;
  const my = (a.coords.y + b.coords.y) / 2;
  // Bow the control point upward for a satellite-route feel
  const lift = 10 + Math.abs(a.coords.x - b.coords.x) * 0.12;
  return `M ${a.coords.x} ${a.coords.y} Q ${mx} ${my - lift} ${b.coords.x} ${b.coords.y}`;
}

